ergebnisse.roh:
{
  "saetze": [
    {
      "text": "Fahrzeuge müssen mindestens zwei Werktage vor geplanter Fahrt bei der Fahrbereitschaft reserviert werden, wobei Datum, voraussichtliche Rückgabezeit und Fahrtziel anzugeben sind.",
      "belege": [
        {
          "bericht": "B8",
          "zitat": "Fahrzeuge werden mindestens zwei Werktage vor der geplanten Fahrt bei der Fahrbereitschaft reserviert. Bei der Reservierung werden Datum, voraussichtliche Rückgabezeit und Fahrtziel angegeben."
        }
      ]
    },
    {
      "text": "Seit dem 01.02.2026 sind Fahrzeuge der Fahrbereitschaft ausschließlich über das Fahrzeugportal im Intranet mindestens drei Werktage vor Fahrtbeginn anzufordern; telefonische Anfragen werden nicht mehr angenommen.",
      "belege": [
        {
          "bericht": "B43",
          "zitat": "seit dem 01.02.2026 Fahrzeuge der Fahrbereitschaft ... ausschließlich über das Fahrzeugportal im Intranet angefordert werden, und zwar mindestens drei Werktage vor Fahrtbeginn. Telefonische Anforderungen werden seitdem nicht mehr angenommen."
        }
      ]
    },
    {
      "text": "Ausgeliehene Dienstfahrzeuge bleiben der ausleihenden Person zugeordnet, die bei Rückgabe den Fahrzeugschlüssel abgibt, den Kilometerstand ins Fahrtenbuch einträgt und die Rückgabe gegenüber der Fahrbereitschaft bestätigt.",
      "belege": [
        {
          "bericht": "B5",
          "zitat": "Ausgeliehene Dienstfahrzeuge ... zurückgegeben. Sie gibt den Fahrzeugschlüssel ... ab und trägt den Kilometerstand ins Fahrtenbuch ein."
        },
        {
          "bericht": "B33",
          "zitat": "Auch bei gemeinsamer Nutzung bleibt das Fahrzeug der ausleihenden Person zugeordnet. Sie gibt das Fahrzeug zurück und bestätigt die Rückgabe gegenüber der Fahrbereitschaft."
        }
      ]
    },
    {
      "text": "Bei der Rückgabe muss das Fahrzeug vollgetankt sein; der Tankstand wird bei Rückgabe vermerkt und das Betanken erfolgt anschließend durch die Fahrbereitschaft.",
      "belege": [
        {
          "bericht": "B5",
          "zitat": "Das Fahrzeug wird vollgetankt zurückgegeben."
        },
        {
          "bericht": "B24",
          "zitat": "Bei der Rückgabe wird außerdem der Tankstand vermerkt, das Betanken übernimmt anschließend die Fahrbereitschaft."
        }
      ]
    },
    {
      "text": "Schäden werden vor Fahrtantritt und bei Rückgabe im Schadensformular mit Kennzeichen und Datum erfasst; das Formular wird zusammen mit dem Fahrzeugschlüssel bei der Fahrbereitschaft abgegeben, jedoch leitet ein festgestellter Schaden keine persönliche Verantwortung ab.",
      "belege": [
        {
          "bericht": "B18",
          "zitat": "Schäden werden vor Fahrtantritt und bei der Rückgabe mit Kennzeichen und Datum im Schadensformular erfasst. Das Formular wird mit dem Fahrzeugschlüssel bei der Fahrbereitschaft abgegeben."
        }
      ]
    },
    {
      "text": "Im Übungsbetrieb auf dem Truppenübungsplatz übernehmen die Kraftfahrer die Fahrzeuge selbst, erfassen Kilometerstand, Tankstand und Vorschäden im Übergabeprotokoll, tanken an der Feldtankstelle selbst und tragen die Menge mit Datum und Unterschrift ins täglich geführte Fahrtenbuch ein, das abends vom Kfz‑Feldwebel geprüft wird; vor Rückgabe muss das Fahrzeug wieder vollgetankt sein.",
      "belege": [
        {
          "bericht": "B45",
          "zitat": "Die Fahrzeuge wurden ... bei der Fahrbereitschaft übernommen. Dabei wurden Kilometerstand, Tankstand und Vorschäden ... erfasst."
        },
        {
          "bericht": "B45",
          "zitat": "Die Kraftfahrer tankten ihre Fahrzeuge selbst an der Feldtankstelle ... Vor der Rückgabe ... war jedes Fahrzeug vollgetankt abzugeben."
        },
        {
          "bericht": "B45",
          "zitat": "Das Fahrtenbuch wurde täglich vom Kraftfahrer geführt und abends vom Kfz‑Feldwebel geprüft."
        }
      ]
    }
  ]
}

